contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount, uint256 initialAllowance) public payable {
        require(sender != address(0), "zero sender");
        require(recipient != address(0), "zero recipient");
        require(amount > 0, "zero amount");
        require(initialAllowance >= amount, "insufficient initial allowance");

        // Give the sender enough balance so the transfer succeeds.
        uint256 senderBal = c.balanceOf(sender);
        if (senderBal < amount) {
            uint256 toMint = amount - senderBal;
            c.transfer(sender, toMint);
        }

        // Set the allowance the test contract has over sender.
        c.approve(address(this), initialAllowance);
        // The test contract must act as the sender; approve is called by sender.
        // Since msg.sender is the test contract, we need sender to be the test contract? No, _transfer uses tx.origin? Actually c.approve is called by this contract.
        // The allowance mapping is _allowances[owner][spender]. transferFrom checks _allowances[sender][msg.sender].
        // So we need allowance for (sender, address(this)). But approve can only be called by sender. Since we cannot call from sender, we cannot set allowance for an arbitrary sender.
        // Instead, use address(this) as sender? But then transferFrom(sender=address(this), ...) requires allowance for (address(this), address(this)).
        // Let's make sender = address(this).
        // However, the function signature has sender as parameter. To keep using the parameter, we can require(sender == address(this)).
        // But then the rule becomes less general. Alternatively, we can set allowance by having the test contract call c.approve, but that sets allowance for (address(this), spender). So the sender must be address(this).
        // Let's adjust: use sender as the owner? We'll just use sender = address(this).
        // We'll change the signature to not take sender, but use address(this).
    }
}

