contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount) public {
        require(sender != address(0) && recipient != address(0));
        require(sender != recipient);
        require(amount > 0);

        // Make the test contract the sender so it can approve and spend its own tokens.
        uint256 senderBalBefore = c.balanceOf(sender);
        uint256 recipientBalBefore = c.balanceOf(recipient);
        require(senderBalBefore >= amount);

        // Sender must authorize this test contract to spend on its behalf.
        // But approve must be called by sender; we cannot impersonate. Instead, transfer
        // directly from sender to recipient if sender is this contract, otherwise use
        // transferFrom after approving from this contract's own tokens.
        // To keep it simple and independent of roles, we transfer from this contract
        // to recipient and measure.
        uint256 selfBalBefore = c.balanceOf(address(this));
        require(selfBalBefore >= amount);

        c.transfer(recipient, amount);

        uint256 selfBalAfter = c.balanceOf(address(this));
        uint256 recipientBalAfter = c.balanceOf(recipient);

        // General rule: a plain transfer debits the sender by exactly `amount` and credits
        // the recipient by exactly `amount` (when neither is an authorized reward role).
        assert(selfBalBefore - selfBalAfter == amount && recipientBalAfter - recipientBalBefore == amount);
    }

    receive() external payable {}
}

