contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount) public payable {
        require(sender != address(0) && recipient != address(0));
        require(sender != recipient);
        require(amount > 0);

        // Ensure the sender has enough balance for the transfer to potentially succeed.
        // If not, the rule would be uninteresting/vacuously revert, so we return early
        // by requiring enough balance. This is a precondition, not a state read on c.
        // (We read balanceOf only through the public getter.)
        require(c.balanceOf(sender) >= amount);

        // Ensure neither address is a role-privileged address, so _transfer takes the
        // plain transfer branch without reward adjustments.
        // Role membership is not publicly observable, but the special behavior only
        // triggers when transfer amount >= minTxnAmount and the contract has enough
        // balance. We avoid the reward/discount branch by using a small amount if
        // possible, but we cannot know minTxnAmount is large. Instead, state the rule
        // for the plain branch and guard by ensuring the contract's own balance is
        // zero; then the reward branch cannot apply (balanceOf(address(this)) == 0 < rewardAmount).
        require(c.balanceOf(address(c)) == 0);

        uint256 senderBefore = c.balanceOf(sender);
        uint256 recipientBefore = c.balanceOf(recipient);
        uint256 totalBefore = c.totalSupply();

        c.transferFrom(sender, recipient, amount);

        uint256 senderAfter = c.balanceOf(sender);
        uint256 recipientAfter = c.balanceOf(recipient);
        uint256 totalAfter = c.totalSupply();

        assert(recipientAfter == recipientBefore + amount &&
               senderAfter == senderBefore - amount &&
               totalAfter == totalBefore);
    }

    receive() external payable {}
}

