contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, address recipient, uint256 amount, uint256 initialAllowance) public {
        // Setup: give the test contract some tokens so it can act as the sender.
        // The test contract is the owner and initial holder, but we cannot rely on that here;
        // instead we just use the owner's balance implicitly. We need an allowance from the owner.
        // Since the test contract is the owner (deployer), we can approve spender from itself.
        c.approve(spender, initialAllowance);

        uint256 allowanceBefore = c.allowance(address(this), spender);
        uint256 spenderBalanceBefore = c.balanceOf(spender);

        bool reverted;
        try c.transferFrom(address(this), spender, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 allowanceAfter = c.allowance(address(this), spender);

        if (reverted) {
            // If the transferFrom reverted, it must be because amount exceeded the allowance,
            // and the allowance must be unchanged.
            assert(amount > allowanceBefore);
            assert(allowanceAfter == allowanceBefore);
        } else {
            // If the transferFrom succeeded, the allowance must have decreased by exactly amount.
            assert(allowanceAfter == allowanceBefore - amount);
        }
    }

    receive() external payable {}
}

