        }

        // No fee should accrue on a plain transfer: _tFeeTotal is exposed publicly.
        uint256 feeTotalAfter = c.totalFees();

        if (!reverted) {
            uint256 afterSender = c.balanceOf(sender);
            uint256 afterRecipient = c.balanceOf(recipient);

            // General rule: a successful plain transfer conserves balances and adds no fees.
            // The reflection mechanism guarantees sender loses exactly amount and recipient gains exactly amount.
            assert(afterRecipient == beforeRecipient + amount);
            assert(afterSender == beforeSender - amount);
            assert(feeTotalAfter == 0);
        } else {
            // If the transfer reverted, c's public surface must be unchanged.
            assert(c.balanceOf(sender) == beforeSender);
            assert(c.balanceOf(recipient) == beforeRecipient);
            assert(c.totalFees() == feeTotalAfter);
        }
    }

    receive() external payable {}
}

