        // call from address(this); to test the non-owner revert path we rely on a
        // precondition that only allows calling changeOwner when address(this) is not
        // the owner -- impossible for a fresh C. Therefore we instead test the
        // owner-success path with a bool that selects whether newOwner is applied.)

        require(impersonateOwner, "non-owner path cannot be reliably exercised without msg.sender control");

        bool reverted;
        try c.changeOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        assert(
            reverted
                ? ownerAfter == ownerBefore
                : ownerAfter == newOwner
        );
    }

    receive() external payable {}
}

