contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 tAmount) public payable {
        require(sender != address(0), "sender zero");
        require(recipient != address(0), "recipient zero");
        require(tAmount > 0, "amount zero");

        // Ensure sender and recipient are allowed roles? Not directly settable; skip if not allowed.
        // We'll assume c's _allowedRoles is set via constructor for deployer? Not exposed.
        // Instead, we test general transfer behavior assuming default roles may revert.
        // We'll capture revert status.
        bool reverted;
        uint256 beforeBalance;
        uint256 afterBalance;

        // Read before balance of recipient
        beforeBalance = c.balanceOf(recipient);

        // Attempt transfer from sender to recipient. This may revert if unauthorized or insufficient balance.
        try c.transferFrom(sender, recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            afterBalance = c.balanceOf(recipient);
            // The recipient's balance must not decrease (general rule: transfers to recipient increase or maintain balance)
            // Actually, for a standard ERC20 transfer, recipient balance increases by tAmount, but here reward may add extra.
            // So afterBalance >= beforeBalance + tAmount should hold if no fee-on-transfer; but this token has rewards.
            // Safer: afterBalance >= beforeBalance (no loss) unless sender == recipient.
            // For sender == recipient, balance may change due to reward logic, but still should not decrease? Actually if reward is taken from address(this) it may increase.
            // General rule: if transfer succeeds and recipient != sender, recipient balance increases by at least tAmount? Not guaranteed with reflection? Reflection uses rate, so balance may vary slightly.
            // We'll assert that afterBalance >= beforeBalance for successful transfers (no negative effect on recipient).
            assert(afterBalance >= beforeBalance);
        } else {
            // If it reverted, we don't assert on balances.
            assert(reverted);
        }
    }

    receive() external payable {}
}

