contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address buyer, uint256 amount) public payable {
        require(buyer != address(0), "zero buyer");
        require(amount > 0, "zero amount");
        require(amount <= c.balanceOf(c.owner()), "amount exceeds owner balance");

        // Owner enables the buyer as an authorized role by making it the pair,
        // which makes _allowedRoles[buyer] true.
        c.changeUniswapV2Pair(buyer);

        uint256 rewardBefore = c.txReward(buyer);
        uint256 buyerBefore = c.balanceOf(buyer);
        uint256 contractBefore = c.balanceOf(address(c));

        // Fund the contract with enough tokens to pay the reward.
        // Since owner is msg.sender of this contract and owns all tokens, transfer to c.
        bool funded;
        if (contractBefore < (amount * c.rewardRate()) / c.percent()) {
            try c.transfer(address(c), amount) { funded = true; } catch { funded = false; }
        } else {
            funded = true;
        }
        require(funded, "funding failed");

        uint256 contractAfterFunding = c.balanceOf(address(c));
        require(contractAfterFunding >= (amount * c.rewardRate()) / c.percent(), "not funded enough");

        // The deciding call: transfer from buyer (authorized role) to a fresh recipient.
        address recipient = address(uint160(uint256(keccak256(abi.encodePacked(buyer, amount)))) | 1);
        require(recipient != address(0) && recipient != buyer, "bad recipient");

        bool reverted;
        try c.transferFrom(buyer, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 rewardAfter = c.txReward(buyer);
        uint256 contractAfter = c.balanceOf(address(c));

        if (!reverted && amount >= c.minTxnAmount()) {
            uint256 expectedReward = (amount * c.rewardRate()) / c.percent();
            uint256 rewardGap = rewardAfter - rewardBefore;
            uint256 contractDrop = contractAfterFunding - contractAfter;
            assert(rewardGap == expectedReward && contractDrop == expectedReward);
        } else {
            assert(rewardAfter == rewardBefore);
        }
    }

    receive() external payable {}
}

